  1	/**
  2	 * Read-only client for the project workflow viewer API (`contracts/projects/README.md`).
  3	 *
  4	 * Every payload is validated against the committed contract schemas before it reaches a component. A
  5	 * response that fails validation is a malformed-payload error: nothing is patched up or substituted.
  6	 * Artifacts and results are only ever requested through the scoped routes of the run being viewed.
  7	 */
  8	import { z } from 'zod'
  9	import {
 10	  isBlockingFinding,
 11	  schemas,
 12	  validateReviewResult,
 13	  validateRunDetail,
 14	  validateRunInputs,
 15	  type Project,
 16	  type ReviewFinding,
 17	  type ReviewResult,
 18	  type RunDetail,
 19	  type RunInputs,
 20	  type RunInputWorker,
 21	  type RunSummary,
 22	  type WorkflowDefinition,
 23	} from '../../contracts/projects/v1.ts'
 24	import { eventSchema, validateWorkerResult, type WorkerResult, type WorkflowEvent } from '../../contracts/workflow/v1.ts'
 25	
 26	export type { Project, ReviewFinding, ReviewResult, RunDetail, RunInputs, RunInputWorker, RunSummary, WorkflowDefinition, WorkerResult, WorkflowEvent }
 27	export { isBlockingFinding }
 28	
 29	/** The contract's "not recorded" 404 codes: a run whose export predates a section, never an error state. */
 30	export const NOT_RECORDED = { review: 'REVIEW_NOT_FOUND', inputs: 'INPUTS_NOT_FOUND' } as const
 31	
 32	export type ApiErrorKind = 'network' | 'http' | 'malformed'
 33	
 34	/** A failed request. `status` is set for HTTP failures; `code` comes from the contract error body when present. */
 35	export class ProjectsApiError extends Error {
 36	  readonly kind: ApiErrorKind
 37	  readonly status: number | null
 38	  readonly code: string | null
 39	  readonly path: string
 40	
 41	  constructor(kind: ApiErrorKind, message: string, path: string, options: { status?: number | null; code?: string | null } = {}) {
 42	    super(message)
 43	    this.name = 'ProjectsApiError'
 44	    this.kind = kind
 45	    this.status = options.status ?? null
 46	    this.code = options.code ?? null
 47	    this.path = path
 48	  }
 49	
 50	  get notFound(): boolean {
 51	    return this.kind === 'http' && this.status === 404
 52	  }
 53	}
 54	
 55	export function describeApiError(error: unknown): string {
 56	  if (error instanceof ProjectsApiError) {
 57	    switch (error.kind) {
 58	      case 'network': return 'The API could not be reached. Check that the server is running, then retry.'
 59	      case 'malformed': return `The API returned data that does not match the projects contract: ${error.message}`
 60	      case 'http': return error.code ? `${error.message} (${error.code}, HTTP ${error.status})` : `${error.message} (HTTP ${error.status})`
 61	    }
 62	  }
 63	  return error instanceof Error && error.message ? error.message : 'An unexpected error occurred.'
 64	}
 65	
 66	const errorBodySchema = z.object({ error: z.object({ code: z.string(), message: z.string() }) })
 67	
 68	function encodeSegments(...segments: string[]): string {
 69	  return segments.map(encodeURIComponent).join('/')
 70	}
 71	
 72	export type RunScope = { projectId: string; workflowId: string; runId: string }
 73	
 74	export const paths = {
 75	  projects: () => '/api/projects',
 76	  workflows: (projectId: string) => `/api/projects/${encodeSegments(projectId)}/workflows`,
 77	  runs: (projectId: string, workflowId: string, options: { limit?: number; cursor?: string | null } = {}) => {
 78	    const query = new URLSearchParams()
 79	    if (options.limit !== undefined) query.set('limit', String(options.limit))
 80	    if (options.cursor) query.set('cursor', options.cursor)
 81	    const suffix = query.size ? `?${query}` : ''
 82	    return `/api/projects/${encodeSegments(projectId)}/workflows/${encodeSegments(workflowId)}/runs${suffix}`
 83	  },
 84	  run: (scope: RunScope) => `/api/projects/${encodeSegments(scope.projectId)}/workflows/${encodeSegments(scope.workflowId)}/runs/${encodeSegments(scope.runId)}`,
 85	  events: (scope: RunScope, after = 0) => `${paths.run(scope)}/events?after=${after}`,
 86	  result: (scope: RunScope, nodeId: string, attempt: number) => `${paths.run(scope)}/results/${encodeSegments(nodeId)}/${attempt}`,
 87	  artifact: (scope: RunScope, artifactId: string) => `${paths.run(scope)}/artifacts/${encodeSegments(artifactId)}`,
 88	  review: (scope: RunScope, attempt: number) => `${paths.run(scope)}/reviews/${attempt}`,
 89	  inputs: (scope: RunScope) => `${paths.run(scope)}/inputs`,
 90	}
 91	
 92	async function request(path: string, signal: AbortSignal | undefined, accept: string): Promise<Response> {
 93	  let response: Response
 94	  try {
 95	    response = await fetch(path, { signal, headers: { Accept: accept } })
 96	  } catch (error) {
 97	    if (signal?.aborted) throw error
 98	    throw new ProjectsApiError('network', error instanceof Error ? error.message : 'Network failure', path)
 99	  }
100	  if (!response.ok) {
101	    let body: unknown = null
102	    try { body = await response.json() } catch { /* not JSON */ }
103	    const parsed = errorBodySchema.safeParse(body)
104	    const message = parsed.success ? parsed.data.error.message : `The API responded with status ${response.status}.`
105	    throw new ProjectsApiError('http', message, path, { status: response.status, code: parsed.success ? parsed.data.error.code : null })
106	  }
107	  return response
108	}
109	
110	async function requestJson<T>(path: string, validate: (input: unknown) => T, signal?: AbortSignal): Promise<T> {
111	  const response = await request(path, signal, 'application/json')
112	  let body: unknown
113	  try {
114	    body = await response.json()
115	  } catch {
116	    throw new ProjectsApiError('malformed', 'the response body is not JSON.', path)
117	  }
118	  try {
119	    return validate(body)
120	  } catch (error) {
121	    throw new ProjectsApiError('malformed', error instanceof z.ZodError ? z.prettifyError(error) : error instanceof Error ? error.message : 'invalid payload', path)
122	  }
123	}
124	
125	export function fetchProjects(signal?: AbortSignal): Promise<Project[]> {
126	  return requestJson(paths.projects(), input => schemas.projectList.parse(input).projects, signal)
127	}
128	
129	export function fetchWorkflows(projectId: string, signal?: AbortSignal): Promise<WorkflowDefinition[]> {
130	  return requestJson(paths.workflows(projectId), input => schemas.workflowList.parse(input).workflows, signal)
131	}
132	
133	export type RunPage = { runs: RunSummary[]; nextCursor: string | null }
134	
135	export function fetchRuns(projectId: string, workflowId: string, options: { cursor?: string | null } = {}, signal?: AbortSignal): Promise<RunPage> {
136	  return requestJson(paths.runs(projectId, workflowId, options), input => {
137	    const page = schemas.runList.parse(input)
138	    for (const run of page.runs) {
139	      if (run.project_id !== projectId || run.workflow_id !== workflowId) throw new Error(`run ${run.run_id} belongs to another scope.`)
140	    }
141	    return { runs: page.runs, nextCursor: page.next_cursor }
142	  }, signal)
143	}
144	
145	export function fetchRunDetail(scope: RunScope, signal?: AbortSignal): Promise<RunDetail> {
146	  return requestJson(paths.run(scope), input => {
147	    const detail = validateRunDetail(input)
148	    if (detail.summary.project_id !== scope.projectId || detail.summary.workflow_id !== scope.workflowId || detail.summary.run_id !== scope.runId) {
149	      throw new Error('the run detail belongs to a different project, workflow or run.')
150	    }
151	    return detail
152	  }, signal)
153	}
154	
155	const eventListSchema = z.strictObject({ events: z.array(eventSchema) })
156	
157	export function fetchEvents(scope: RunScope, signal?: AbortSignal): Promise<WorkflowEvent[]> {
158	  return requestJson(paths.events(scope, 0), input => {
159	    const events = eventListSchema.parse(input).events
160	    // Deduplicate by sequence and keep the persisted order; the run ID must be this run's.
161	    const seen = new Set<number>()
162	    const unique: WorkflowEvent[] = []
163	    for (const event of events) {
164	      if (event.run_id !== scope.runId) throw new Error(`event ${event.event_id} belongs to run ${event.run_id}.`)
165	      if (seen.has(event.sequence)) continue
166	      seen.add(event.sequence)
167	      unique.push(event)
168	    }
169	    return unique.sort((a, b) => a.sequence - b.sequence)
170	  }, signal)
171	}
172	
173	/** Only results published under this run's scoped `results/` route are fetched; anything else is refused. */
174	export function scopedResultPath(scope: RunScope, resultUri: string): string | null {
175	  const prefix = `${paths.run(scope)}/results/`
176	  if (!resultUri.startsWith(prefix)) return null
177	  const rest = resultUri.slice(prefix.length).split('/')
178	  if (rest.length !== 2 || rest.some(segment => segment === '') || !/^[1-9][0-9]*$/.test(rest[1])) return null
179	  return resultUri
180	}
181	
182	export function fetchWorkerResult(scope: RunScope, resultPath: string, signal?: AbortSignal): Promise<WorkerResult> {
183	  return requestJson(resultPath, input => {
184	    const result = validateWorkerResult(input)
185	    if (result.run_id !== scope.runId) throw new Error(`the result belongs to run ${result.run_id}.`)
186	    return result
187	  }, signal)
188	}
189	
190	/** Text artifacts (logs, reports, patches) are read as plain text and rendered as text, never as HTML. */
191	export async function fetchArtifactText(scope: RunScope, artifactId: string, signal?: AbortSignal): Promise<string> {
192	  const response = await request(paths.artifact(scope, artifactId), signal, 'text/plain, */*')
193	  return response.text()
194	}
195	
196	/** Only reviews published under this run's scoped `reviews/` route are fetched; anything else is refused. */
197	export function scopedReviewPath(scope: RunScope, resultUri: string): string | null {
198	  const prefix = `${paths.run(scope)}/reviews/`
199	  if (!resultUri.startsWith(prefix)) return null
200	  if (!/^[1-9][0-9]*$/.test(resultUri.slice(prefix.length))) return null
201	  return resultUri
202	}
203	
204	export function fetchReviewResult(scope: RunScope, reviewPath: string, signal?: AbortSignal): Promise<ReviewResult> {
205	  return requestJson(reviewPath, input => {
206	    const review = validateReviewResult(input)
207	    if (review.run_id !== scope.runId) throw new Error(`the review belongs to run ${review.run_id}.`)
208	    return review
209	  }, signal)
210	}
211	
212	export function fetchRunInputs(scope: RunScope, signal?: AbortSignal): Promise<RunInputs> {
213	  return requestJson(paths.inputs(scope), input => {
214	    const inputs = validateRunInputs(input)
215	    if (inputs.run_id !== scope.runId) throw new Error(`the inputs belong to run ${inputs.run_id}.`)
216	    return inputs
217	  }, signal)
218	}
219	
220	/** Whether a failure is the contract's 404 for a section the run's export does not carry. */
221	export function isNotRecorded(error: unknown, code: string): boolean {
222	  return error instanceof ProjectsApiError && error.notFound && error.code === code
223	}
224	
225	/** Resolves to null when the section is not recorded (the contract's 404 code); every other failure propagates. */
226	export async function orNotRecorded<T>(request: Promise<T>, code: string): Promise<T | null> {
227	  try {
228	    return await request
229	  } catch (error) {
230	    if (isNotRecorded(error, code)) return null
231	    throw error
232	  }
233	}

.status-badge { display: inline-flex; align-items: center; gap: 4px; padding: 1px 8px; border-radius: 999px; font-size: 0.8rem; font-weight: 600; border: 1px solid var(--border); background: var(--surface-alt); color: var(--text); white-space: nowrap; }
.status-badge::before { content: ''; width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted); }
.status-succeeded::before { background: var(--node-location-stroke); }
.status-failed { border-color: var(--danger-border); color: var(--danger-text); background: var(--danger-bg); }
.status-failed::before { background: var(--danger-text); }
.status-running::before { background: var(--accent); }
.status-awaiting_approval, .status-paused { border-color: var(--node-directory-stroke); }
.status-awaiting_approval::before, .status-paused::before { background: var(--node-directory-stroke); }
.status-cancelled::before { background: var(--text-muted); }

.projects-facts { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 6px 16px; margin: 8px 0; }
.projects-facts > div { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.projects-facts dt { font-size: 0.8rem; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.02em; }
.projects-facts dd { margin: 0; overflow-wrap: anywhere; }
.projects-facts code, .workspace-projects code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85em; background: var(--surface-alt); padding: 1px 4px; border-radius: 3px; overflow-wrap: anywhere; }

/* Workflow DAG */
.workflow-graph-scroll { overflow: auto; border: 1px solid var(--border); border-radius: 8px; background: var(--surface-alt); padding: 4px; }
.workflow-graph { display: block; }
.workflow-edge { fill: none; stroke: var(--edge); stroke-width: 1.5; }
.workflow-edge-arrow { fill: var(--edge); }
.workflow-node { cursor: default; outline: none; }
.workflow-node[role='button'] { cursor: pointer; }
.workflow-node-shape { fill: var(--surface); stroke: var(--node-file-stroke); stroke-width: 1.5; }
.workflow-node-worker .workflow-node-shape { stroke: var(--node-source-stroke); }
.workflow-node-verification .workflow-node-shape { stroke: var(--node-directory-stroke); }
.workflow-node-review .workflow-node-shape, .workflow-node-integration .workflow-node-shape { stroke: var(--node-location-stroke); }
.workflow-node-status-bar { fill: var(--text-muted); }
.workflow-node.is-succeeded .workflow-node-status-bar { fill: var(--node-location-stroke); }
.workflow-node.is-failed .workflow-node-status-bar { fill: var(--danger-text); }
.workflow-node.is-failed .workflow-node-shape { stroke: var(--danger-text); fill: var(--danger-bg); }
.workflow-node.is-running .workflow-node-status-bar { fill: var(--accent); }
.workflow-node.is-awaiting_approval .workflow-node-status-bar, .workflow-node.is-paused .workflow-node-status-bar { fill: var(--node-directory-stroke); }
.workflow-node.is-awaiting_approval .workflow-node-shape { stroke: var(--node-directory-stroke); fill: var(--node-directory-fill); stroke-dasharray: 5 3; }
.workflow-node.is-pending .workflow-node-shape { stroke-dasharray: 3 3; }
.workflow-node.is-definition .workflow-node-status-bar { fill: var(--edge); }
.workflow-node.is-selected .workflow-node-shape { stroke: var(--accent); stroke-width: 3; }
.workflow-node-focus { fill: none; stroke: var(--focus); stroke-width: 3; stroke-dasharray: 4 3; display: none; }
.workflow-node:focus-visible .workflow-node-focus { display: block; }
.workflow-node-label { font-size: 12px; font-weight: 600; fill: var(--text); }
.workflow-node-meta { font-size: 10px; fill: var(--text-muted); }

/* Run view */
.run-status-line { margin: 4px 0 8px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.run-columns { display: grid; grid-template-columns: minmax(220px, 1fr) minmax(0, 2fr); gap: 16px; margin-top: 8px; }
.run-node-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px; }
.run-node-link { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border: 1px solid transparent; border-radius: 6px; text-decoration: none; color: var(--text); min-height: 44px; }
.run-node-link:hover { background: var(--surface-alt); }
.run-node-link[aria-current='page'] { border-color: var(--accent); background: var(--surface-alt); }
.run-node-label { font-weight: 600; }
.run-node-meta { font-size: 0.85rem; color: var(--text-muted); display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.run-detail-panel { min-width: 0; border: 1px solid var(--border); border-radius: 8px; padding: 12px; background: var(--surface); }
.node-detail h3 { margin-top: 0; }
.node-detail-id { font-weight: 400; font-size: 0.9rem; }
.node-detail-footnote, .run-footnote { margin-top: 12px; }
.evidence-section { margin-top: 8px; }
.evidence-list { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 6px; }
.evidence-list p { margin: 0; }
.evidence-files { font-size: 0.9rem; }
.worker-summary { margin: 8px 0; }
.check { padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px; list-style: none; margin-left: -20px; }
.check-passed { border-left: 4px solid var(--node-location-stroke); }
.check-failed { border-left: 4px solid var(--danger-text); }
.check-deferred { border-left: 4px solid #b8860b; }
.check-deferred .check-exit { color: #8a6508; }
.lane-result { margin-top: 12px; padding-top: 8px; border-top: 1px solid var(--border, #ccc); }
.lane-result h5 { margin: 0 0 8px; font-size: 1rem; }
.check-head { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; justify-content: space-between; }
.check-exit { font-size: 0.85rem; font-weight: 600; }
.check-failed .check-exit { color: var(--danger-text); }
.check-meta { margin: 4px 0; }
.check-log { display: flex; flex-direction: column; gap: 6px; font-size: 0.9rem; }
.artifact-text { display: flex; flex-direction: column; gap: 6px; align-items: flex-start; }
.artifact-log { margin: 0; width: 100%; max-height: 320px; overflow: auto; padding: 8px 10px; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.8rem; line-height: 1.45; white-space: pre-wrap; overflow-wrap: anywhere; }
.artifact-screenshot { display: block; max-width: 100%; height: auto; border: 1px solid var(--border); border-radius: 6px; background: var(--surface-alt); }
.evidence-screenshots { list-style: none; padding-left: 0; }
.event-list { margin: 0; padding-left: 20px; display: flex; flex-direction: column; gap: 4px; font-size: 0.9rem; overflow-wrap: anywhere; }
.event-seq { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; color: var(--text-muted); }
.event-type { font-weight: 600; }

/* Run views: tabs above the graph, the Assignment tab, worker input panels and the review panel */
.run-tabs { padding: 8px 0 0; margin-top: 12px; flex-wrap: wrap; }
.run-body, .assignment { min-width: 0; }
.assignment > h3 { margin-top: 12px; }
.assignment-worker { margin-top: 16px; padding: 12px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); min-width: 0; }
.assignment-worker h4 { margin-top: 0; overflow-wrap: anywhere; }
.assignment-scenarios { margin-top: 4px; }
.workspace-projects h5 { margin: 12px 0 4px; font-size: 0.9rem; }
.task-rendered { padding: 8px 12px; border: 1px solid var(--border); border-radius: 6px; background: var(--surface); min-width: 0; overflow-wrap: anywhere; }
.task-rendered .markdown { max-width: none; }
.task-source { margin: 0; padding: 10px 12px; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.85rem; line-height: 1.5; white-space: pre-wrap; overflow-wrap: anywhere; overflow: auto; max-height: 480px; background: var(--surface-alt); border: 1px solid var(--border); border-radius: 6px; tab-size: 4; }
.task-source:focus-visible, .task-prompt summary:focus-visible, .check:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }
.task-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; }
.task-head h4 { margin: 12px 0 6px; }
.task-toggle { display: inline-flex; gap: 4px; }
/* The highlighted requirement keeps readable contrast in both schemes (tokens in index.css) and a focus-coloured ring so it stands out from the surrounding source. */
.task-highlight { background: var(--mark-bg); color: var(--mark-text); padding: 1px 2px; border-radius: 3px; outline: 2px solid var(--focus); outline-offset: 1px; }
.task-checks li { overflow-wrap: anywhere; }
.task-check-status { font-size: 0.9rem; margin-top: 2px; }
.task-prompt { margin-top: 12px; }
.task-prompt summary { cursor: pointer; padding: 8px 0; }
.task-prompt .task-source { margin-top: 6px; }
.worker-stop { margin: 8px 0 0; font-size: 0.9rem; }
.review-verdict-line { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: 8px 0; }
.review-summary { margin: 0 0 8px; font-weight: 600; overflow-wrap: anywhere; }
.finding-group { margin-top: 8px; min-width: 0; }
.finding-group .table-wrap { overflow: auto; max-width: 100%; }
.findings-table { border-collapse: collapse; width: 100%; min-width: 560px; font-size: 0.9rem; }
.findings-table th, .findings-table td { border: 1px solid var(--border); padding: 6px 8px; text-align: left; vertical-align: top; overflow-wrap: anywhere; }
.findings-table th { background: var(--surface-alt); white-space: nowrap; }
.findings-table q { quotes: '\201C' '\201D'; }
.finding-severity { font-weight: 700; }
.finding-blocking .finding-severity { color: var(--danger-text); }
.finding-blocking > td:first-child { border-left: 4px solid var(--danger-text); }
.finding-task-link, .finding-task-note { display: block; margin-top: 4px; font-size: 0.85rem; }

@media (max-width: 760px) {
  .run-columns { grid-template-columns: 1fr; }
  .workspace-projects { padding: 10px; }
  .projects-facts { grid-template-columns: 1fr; }
  .status-badge { white-space: normal; }
  .task-source { max-height: 360px; }
}

.review-findings-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; }
.review-findings-head h4 { margin: 12px 0 6px; }
.review-group-toggle { display: inline-flex; align-items: center; gap: 6px; flex-wrap: wrap; }
