              <div className="review-group-toggle" role="group" aria-label="Group findings by">
                <span className="projects-muted">Group by</span>
                <button type="button" className="button button-small" aria-pressed={groupBy === 'disposition'} data-testid="group-by-disposition" onClick={() => setGroupBy('disposition')}>Disposition</button>
                <button type="button" className="button button-small" aria-pressed={groupBy === 'worker'} data-testid="group-by-worker" onClick={() => setGroupBy('worker')}>Worker</button>
                <button type="button" className="button button-small" aria-pressed={groupBy === 'reviewer'} data-testid="group-by-reviewer" onClick={() => setGroupBy('reviewer')}>Reviewer</button>
              </div>
            </>
          )}
        </div>
        {populated.length === 0 ? (
          <p className="projects-muted" data-testid="findings-empty">
            {reviewerFilter !== null ? `Reviewer ${reviewerFilter} recorded no findings.` : several ? 'No reviewer recorded a finding.' : 'The reviewer recorded no findings.'}
          </p>
        ) : populated.map(group => (
          <section key={group.key} className="finding-group" {...group.attributes} aria-labelledby={`findings-${group.key}`}>
            <h5 id={`findings-${group.key}`}>{group.label} ({group.findings.length})</h5>
            <div className="table-wrap">
              <table className="findings-table">
                <thead>
                  <tr><th scope="col">Severity</th><th scope="col">Message</th><th scope="col">Worker</th><th scope="col">Reviewer</th><th scope="col">Requirement</th></tr>
                </thead>
                <tbody>
                  {group.findings.map((finding, index) => (
                    <FindingRow key={`${group.key}-${index}`} finding={finding} scope={scope} definitionNodes={definitionNodes} inputs={inputs} onOpenRequirement={onOpenRequirement} onOpenFile={onOpenFile} capturedFiles={capturedFiles} />
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        ))}
        <p className="projects-muted">
          A finding links to a captured file only where its message names the file's path verbatim. Blocking means an unresolved P0 or P1 finding from any reviewer; a quote links only where the task text contains it verbatim. Workers are the lanes this run had{lanes.length > 0 ? ` (${lanes.join(', ')})` : ''}; “multiple workers” covers findings that concern more than one lane. Reviewer names the reviewer that raised the finding; the same finding raised by several reviewers is listed once per reviewer, never merged.
        </p>
      </section>
    </div>
  )
}

/**
 * The Result section of a review node: the persisted combined verdict, every reviewer's identity and outcome, the bundle,
 * the unioned findings and the diff. A run whose export predates review results (404 REVIEW_NOT_FOUND) is a "not recorded"
 * state, not an error.
 */
export function ReviewPanel({ scope, node, definitionNodes, snapshotNodes, inputs, refreshToken, onNavigate, onOpenRequirement, onOpenFile, onTransport }: Props) {
  // The snapshot links the recorded review; an older export has no link, so the first attempt is asked for once the node ran.
  const reviewPath = node.result_uri !== null
    ? scopedReviewPath(scope, node.result_uri)
    : node.status === 'pending' ? null : paths.review(scope, Math.max(node.attempt, 1))
  const unscoped = node.result_uri !== null && reviewPath === null
  const load = useCallback((signal: AbortSignal) => fetchReviewResult(scope, reviewPath!, signal), [scope, reviewPath])
  // The fallback path before a review is recorded equals the linked one after, so the key also names what the node shows.
  const { state, reload } = useResource(reviewPath === null ? null : `${reviewPath}|${node.result_uri ?? node.status}`, load, refreshToken)
  const none = (
    <p className="projects-muted" data-testid="review-none">
      No review recorded for this run: either the review has not happened or the run's export predates review results (re-export it with the workflow CLI).
    </p>
  )
  if (unscoped) {
    return (
      <p className="projects-error-inline" role="alert" data-testid="result-unscoped">
        The review link <code>{node.result_uri}</code> is outside this run's reviews route and was not fetched.
      </p>
    )
  }
  if (reviewPath === null) return none
  if (state.status === 'loading' || state.status === 'idle') return <LoadingPanel>Loading the recorded review…</LoadingPanel>
  if (state.status === 'error') {
    if (isNotRecorded(state.error, NOT_RECORDED.review)) return none
    return <ErrorPanel error={state.error} what="The recorded review" onRetry={reload} />
  }
  return (
    <ReviewResultView
      review={state.data}
      scope={scope}
      definitionNodes={definitionNodes}
      snapshotNodes={snapshotNodes}
      inputs={inputs}
      refreshToken={refreshToken}
      onNavigate={onNavigate}
      onOpenRequirement={onOpenRequirement}
      onOpenFile={onOpenFile}
      onTransport={onTransport}
    />
  )
}
     1	/**
     2	 * Per-reviewer wording for the review node. A review result always carries `reviewers`, one entry per reviewer the run
     3	 * declared (one named `review` for exports recorded before the list existed, filled by the adapter), so nothing here has
     4	 * a single-reviewer case: the combined verdict is unanimous, and a blocked run is explained by the reviewers that caused it.
     5	 * Pure helpers, kept out of the component file so it only exports components.
     6	 */
     7	import { isBlockingFinding, type ReviewFinding, type ReviewResult } from './api.ts'
     8	
     9	export type Reviewer = ReviewResult['reviewers'][number]
    10	
    11	const SEVERITIES: readonly ReviewFinding['severity'][] = ['P0', 'P1', 'P2']
    12	
    13	/**
    14	 * How a reviewer ended, in the contract's vocabulary (`REVIEWER_STATUSES` in `contracts/projects/v1.ts`): `accepted` (its
    15	 * completion file was accepted), `blocked` (its verdict, an unresolved P0/P1, a rejected file or the review deadline
    16	 * blocked the run), `superseded` (stopped after the run was decided while it was still working) or `pending` (no verdict
    17	 * recorded yet). The contract records no separate status for the deadline or a rejected file: both are `blocked` with a
    18	 * null verdict, so the wording for them is derived from `verdict` in `blockingReason`, never from an invented status.
    19	 */
    20	const STATUS_WORDING: Readonly<Record<Reviewer['status'], string>> = {
    21	  accepted: 'completion file accepted',
    22	  blocked: 'blocked',
    23	  superseded: 'stopped after the combined decision',
    24	  pending: 'no verdict recorded yet',
    25	}
    26	
    27	export function statusWording(status: Reviewer['status']): string {
    28	  return STATUS_WORDING[status]
    29	}
    30	
    31	/** Whether the reviewer was stopped because of another reviewer's outcome rather than its own. */
    32	function superseded(reviewer: Pick<Reviewer, 'status'>): boolean {
    33	  return reviewer.status === 'superseded'
    34	}
    35	
    36	/**
    37	 * Why this reviewer's own outcome blocks the run, or null when it does not: a blocked verdict; an approval that left an
    38	 * unresolved P0/P1; or a blocked status without any verdict, which the contract records for both the expired review
    39	 * deadline and a rejected completion file (it does not say which).
    40	 */
    41	export function blockingReason(reviewer: Pick<Reviewer, 'status' | 'verdict' | 'findings'>): string | null {
    42	  if (reviewer.verdict === 'blocked') return 'blocked the candidate'
    43	  if (reviewer.verdict === 'approved') return reviewer.findings.some(isBlockingFinding) ? 'approved with an unresolved P0/P1 finding' : null
    44	  if (reviewer.status === 'blocked') return 'delivered no verdict: the review deadline expired or its completion file was rejected'
    45	  return null
    46	}
    47	
    48	/**
    49	 * One line for the reviewer strip: how the reviewer ended, with the blocking reason when it has one. A reviewer without a
    50	 * verdict says so: superseded before deciding, pending and not yet launched, or pending after its launch.
    51	 */
    52	export function outcomeWording(reviewer: Pick<Reviewer, 'status' | 'verdict' | 'findings' | 'launched_at'>): string {
    53	  const reason = blockingReason(reviewer)
    54	  if (reason !== null) return reason
    55	  if (superseded(reviewer)) return reviewer.verdict === null ? `${statusWording(reviewer.status)}, no verdict` : statusWording(reviewer.status)
    56	  if (reviewer.status === 'pending') return reviewer.launched_at === null ? 'not launched, no verdict recorded yet' : statusWording(reviewer.status)
    57	  return statusWording(reviewer.status)
    58	}
    59	
    60	/** "1 P1, 2 P2" in severity order, listing only the severities present; "no findings" when the list is empty. */
    61	export function severityCounts(findings: readonly Pick<ReviewFinding, 'severity'>[]): string {
    62	  if (findings.length === 0) return 'no findings'
    63	  return SEVERITIES
    64	    .map(severity => [severity, findings.filter(finding => finding.severity === severity).length] as const)
    65	    .filter(([, count]) => count > 0)
    66	    .map(([severity, count]) => `${count} ${severity}`)
    67	    .join(', ')
    68	}
    69	
    70	function list(items: readonly string[]): string {
    71	  if (items.length <= 1) return items.join('')
    72	  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`
    73	}
    74	
    75	/**
    76	 * Why a blocked review is blocked, naming the reviewers whose own outcome caused it (a blocked verdict, an unresolved
    77	 * P0/P1, the deadline or a rejected file), then the reviewers stopped because of it. Null for an approved review.
    78	 */
    79	export function blockedByWording(review: Pick<ReviewResult, 'verdict' | 'reviewers'>): string | null {
    80	  if (review.verdict !== 'blocked') return null
    81	  const reasons = review.reviewers.flatMap(reviewer => {
    82	    const reason = blockingReason(reviewer)
    83	    return reason === null ? [] : [`${reviewer.reviewer_id} (${reason})`]
    84	  })
    85	  const stopped = review.reviewers.filter(superseded).map(reviewer => reviewer.reviewer_id)
    86	  const head = reasons.length === 0
    87	    ? 'Blocked: the combined verdict is blocked although no reviewer recorded a blocking outcome.'
    88	    : `Blocked by ${list(reasons)}.`
    89	  const tail = stopped.length === 0 ? '' : ` ${list(stopped)} ${stopped.length === 1 ? 'was' : 'were'} superseded: stopped after that decision, no verdict recorded.`
    90	  return head + tail
    91	}

